<script lang="ts">
  import { onMount } from 'svelte'
  import { ws, fmt, num, gases, gasLabels, stateLabels } from '../lib/sim.svelte'
  import Confirm from '../components/Confirm.svelte'
  import Trend from '../components/Trend.svelte'
  let pending = $state<'pause' | 'resume' | 'stop' | 'emergency' | 'review' | 'archive' | null>(null)
  let note = $state('')
  let tab = $state(0)
  onMount(() => { if (ws.run) void ws.loadRecentSamples(ws.run.id) })
  const explanations: Record<string,string> = { pause:'暂停后关闭反应气路，保存当前阶段。恢复前请确认原因已解除。', resume:'恢复先前阶段。确认仿真故障场景已解除。', stop:'停止实验，关闭反应气路，进入数据复核。', emergency:'紧急处置关闭反应气路并锁定实验；不能直接恢复。', review:'记录复核结论。紧急处置或重启后的实验也只能经过复核。', archive:'归档已复核的实验，随后可生成技术记录。' }
  async function submit() { if (!ws.run || !pending) return; const action = pending; pending = null; await ws.action(ws.run.id, action, note); note = '' }
</script>
{#if ws.run}
  <section class="hero"><div class="hero-main"><p class="eyebrow">EXPERIMENT #{ws.run.id}</p><h2>{ws.run.name}</h2><p>{stateLabels[ws.run.state] ?? ws.run.state} · 样品 {ws.run.sample.name} · 启动 {fmt(ws.run.started_at)}</p><div class="action-row">
    {#if ['PURGE','REACTION','COOLING'].includes(ws.run.state)}<button class="button secondary" onclick={() => pending = 'pause'}>暂停</button><button class="button secondary" onclick={() => pending = 'stop'}>停止</button><button class="button danger" onclick={() => pending = 'emergency'}>紧急处置</button>{/if}
    {#if ws.run.state === 'PAUSED'}<button class="button primary" disabled={ws.settings?.scenario !== 'normal'} onclick={() => pending = 'resume'}>恢复</button><button class="button secondary" onclick={() => pending = 'stop'}>停止</button><button class="button danger" onclick={() => pending = 'emergency'}>紧急处置</button>{/if}
    {#if ['REVIEW','RECOVERY_REQUIRED','EMERGENCY'].includes(ws.run.state)}<button class="button primary" onclick={() => pending = 'review'}>数据复核</button>{/if}
    {#if ws.run.state === 'REVIEWED'}<button class="button primary" onclick={() => pending = 'archive'}>归档实验</button>{/if}
  </div></div><div class="hero-side"><div><span>当前阶段</span><strong>{stateLabels[ws.run.state]}</strong></div><div><span>阶段进度</span><strong>{num(ws.run.stage_elapsed, 0)} s</strong></div><div><span>最新采样</span><strong>{fmt(ws.snapshot?.sampled_at)}</strong></div></div></section>
  {#if ws.run.state === 'PAUSED' || ws.run.state === 'EMERGENCY' || ws.run.state === 'RECOVERY_REQUIRED'}<div class="callout warn">当前实验处于安全处置状态。反应气已关闭；旧采样不会显示为有效实时读数。</div>{/if}
  <div class="tabs">{#each ['运行监控','实时趋势','控制记录'] as label,i}<button class:active={tab === i} onclick={() => tab = i}>{label}</button>{/each}</div>
  {#if tab === 0}<div class="metric-grid"><div class="metric"><div class="metric-label">温度</div><div class="metric-value">{ws.fresh ? num(ws.snapshot?.values?.temperature_c,1) : '—'} <em>℃</em></div></div><div class="metric"><div class="metric-label">质量</div><div class="metric-value">{ws.fresh ? num(ws.snapshot?.values?.weight_g,3) : '—'} <em>g</em></div></div><div class="metric"><div class="metric-label">阶段</div><div class="metric-value">{ws.run.stage_index+1} <em>/ {ws.run.recipe_snapshot.stages?.length}</em></div></div><div class="metric"><div class="metric-label">采样总数</div><div class="metric-value">{ws.sampleTotal}</div><div class="metric-meta">最新质量标记：{ws.samples.at(-1)?.quality ?? '未知'}</div></div></div><section class="panel"><div class="panel-header"><h2>供气流量 · L/min</h2></div><div class="gas-grid">{#each gases as gas}<div class="gas-readout"><span>{gasLabels[gas]}</span><strong>{ws.fresh ? num(ws.snapshot?.values?.flows[gas]) : '—'}</strong></div>{/each}</div></section><section class="panel stage-summary"><div class="panel-header"><h2>配方阶段目标</h2></div><div class="panel-body detail-grid"><div><span>阶段名称</span><strong>{ws.run.recipe_snapshot.stages?.[ws.run.stage_index]?.name ?? '—'}</strong></div><div><span>目标温度</span><strong>{num(ws.run.recipe_snapshot.stages?.[ws.run.stage_index]?.temperature_c,1)} ℃</strong></div><div><span>阶段时长</span><strong>{ws.run.recipe_snapshot.stages?.[ws.run.stage_index]?.duration_s ?? '—'} s</strong></div></div></section>{/if}
  {#if tab === 1}{#if ws.samples.length}<div class="two-charts"><section class="panel"><div class="panel-header"><h2>温度趋势</h2></div><div class="panel-body"><Trend samples={ws.samples} field="temperature_c" label="温度 / ℃"/></div></section><section class="panel"><div class="panel-header"><h2>质量趋势</h2></div><div class="panel-body"><Trend samples={ws.samples} field="weight_g" label="质量 / g" color="#f59e0b"/></div></section></div>{:else}<div class="empty">等待首个有效采样</div>{/if}<p class="muted">趋势按需读取最近 300 点；过期和故障采样不参与曲线。</p>{/if}
  {#if tab === 2}<section class="panel"><div class="panel-header"><h2>控制与安全记录</h2></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>动作</th><th>说明</th></tr></thead><tbody>{#each ws.audit.filter(a => a.run_id === ws.run?.id) as event}<tr><td>{fmt(event.created_at)}</td><td>{event.action}</td><td>{event.detail}</td></tr>{:else}<tr><td colspan="3" class="empty">暂无记录</td></tr>{/each}</tbody></table></div></section>{/if}
{:else}<div class="empty-state"><h3>没有正在处理的实验</h3><p>从实验准备开始建立仿真实验。已归档记录可在历史页面查看。</p><button class="button primary" onclick={() => ws.navigate('preflight')}>进入实验准备</button></div>{/if}
{#if pending}<Confirm title={`${pending === 'emergency' ? '紧急处置' : pending === 'review' ? '数据复核' : '确认操作'}`} detail={explanations[pending]} confirmText="确认执行" danger={pending === 'emergency'} requireNote={pending === 'review'} bind:note oncancel={() => pending = null} onconfirm={submit}/>{/if}
